1305:   if (levitationGlow) levitationGlow.material.opacity = .36 + (Math.sin(elapsed * 1.7) + 1) * .045;
1306:   if (levitationLight) levitationLight.intensity = 3.8 + (Math.sin(elapsed * 2.1) + 1) * .8;
1307:   const pulse = 1 + Math.sin(elapsed * 4.2) * .018;
1308:   if (model.children.length) {
1309:     // Profile-specific blade meshes breathe together; pulse rings ripple independently.
1310:     model.children.forEach(child => {
1311:       if (child.userData.bladeGlow && child.material) child.material.opacity = .14 + (Math.sin(elapsed * 3.2) + 1) * .025;
1312:       if (child.userData.pulseRing) child.material.opacity = .42 + (Math.sin(elapsed * 5 - child.userData.pulseRing * .8) + 1) * .22;
1313:     });
1314:   }
1315:   turntableEdge.material.emissiveIntensity = .22 + (pulse - 1) * 3;
1316:   auctionSaberRoot.rotation.y += (rotationY - auctionSaberRoot.rotation.y) * .035;
1317:   auctionSaberRoot.rotation.x += (rotationX - auctionSaberRoot.rotation.x) * .035;
1318:   collectionSaberRoot.rotation.y += (rotationY - collectionSaberRoot.rotation.y) * .025;
1319:   collectionSaberRoot.position.y = .12 + Math.sin(elapsed * 1.35) * .08;
1320:   renderer.render(scene, camera);
1321:   if ($('saleOverlay').classList.contains('open')) auctionRenderer.render(auctionScene, auctionCamera);
1322:   if ($('collectionOverlay').classList.contains('open') && collection.length) collectionRenderer.render(collectionScene, collectionCamera);
1323: }
1324: renderSteps(); renderOptions(); updateUI(); updateCollectionCount(); syncBladeToggle(); rebuildSaber(); animate();

.icon-button{width:29px;height:29px;border:1px solid #48514b;color:#b5beb6;background:#1a201d;font-size:18px;cursor:pointer;transition:.2s}
.icon-button:hover{color:var(--acid);border-color:var(--acid)}
