function buildDisassemblySaber() {
  disassemblyRoot.clear();
  disassemblyPieces = [];
  disassemblyClone = model.clone(true);
  disassemblyClone.traverse(child => {
    if (child.isLight) child.visible = false;
    if (child.isMesh && child.material && child.material.isMeshBasicMaterial && child.position.y > 1.02) child.visible = false;
  });
  disassemblyRoot.add(disassemblyClone);
  const meshes = [];
  disassemblyClone.traverse(child => { if (child.isMesh && child.visible) meshes.push(child); });
  const groupY = [-1.52, -.42, .72, 1.88];
  const groupRadius = [1.5, 1.82, 1.72, 1.42];
  const golden = Math.PI * (3 - Math.sqrt(5));
  meshes.forEach((mesh, index) => {
    const y = mesh.position.y;
    const group = y < -.44 ? 0 : y < .12 ? 1 : y < .72 ? 2 : 3;
    const radial = Math.hypot(mesh.position.x, mesh.position.z);
    const angle = radial > .035
      ? Math.atan2(mesh.position.z, mesh.position.x) + (Math.random() - .5) * .38
      : index * golden + (Math.random() - .5) * .5;
    const radius = groupRadius[group] * (.62 + Math.random() * .52);
    const target = new THREE.Vector3(
      Math.cos(angle) * radius + (Math.random() - .5) * .2,
      groupY[group] + (Math.random() - .5) * .26,
      Math.sin(angle) * radius + (Math.random() - .5) * .2
    );
    const targetQuat = new THREE.Quaternion().setFromEuler(new THREE.Euler(
      (Math.random() - .5) * 1.15,
      Math.random() * Math.PI * 2,
      (Math.random() - .5) * 1.15
    ));
    disassemblyPieces.push({
      mesh,
      home: mesh.position.clone(),
      homeQuat: mesh.quaternion.clone(),
      target,
      targetQuat,
      delay: Math.min(.34, group * .065 + Math.random() * .13),
      phase: Math.random() * Math.PI * 2
    });
  });
  $('disassemblyPieceCount').textContent = `${String(disassemblyPieces.length).padStart(2, '0')} PIECES · 04 ASSEMBLIES`;
}

