    glow.addColorStop(0, `rgba(255,255,255,${.65 * headLife})`);
    glow.addColorStop(.4, `rgba(${slicer.bladeRgb},${.28 * headLife})`);
    glow.addColorStop(1, `rgba(${slicer.bladeRgb},0)`);
